package com.example.lambda;

import io.quarkus.amazon.lambda.http.model.AwsProxyRequest;
import io.quarkus.amazon.lambda.http.model.AwsProxyResponse;
import com.amazonaws.services.lambda.runtime.Context;
import com.amazonaws.services.lambda.runtime.RequestHandler;

import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.TimeUnit;

public class ProductHandler implements RequestHandler<AwsProxyRequest, AwsProxyResponse> {

    // In-memory response cache keyed by request path
    private static final ConcurrentHashMap<String, CachedResponse> responseCache = new ConcurrentHashMap<>();
    private static final long CACHE_TTL_MS = TimeUnit.MINUTES.toMillis(5);

    @Override
    public AwsProxyResponse handleRequest(AwsProxyRequest request, Context context) {
        String path = request.getPath();
        String hostHeader = request.getMultiValueHeaders() != null 
            ? request.getMultiValueHeaders().getFirst("Host") 
            : null;
        String xForwardedHost = request.getMultiValueHeaders() != null
            ? request.getMultiValueHeaders().getFirst("X-Forwarded-Host")
            : null;

        // Build cache key using path and forwarded host for multi-tenant routing
        String cacheKey = buildCacheKey(path, xForwardedHost != null ? xForwardedHost : hostHeader);

        // Check cache
        CachedResponse cached = responseCache.get(cacheKey);
        if (cached != null && !cached.isExpired()) {
            context.getLogger().log("Cache HIT for key: " + cacheKey);
            return cached.getResponse();
        }

        // Generate fresh response
        AwsProxyResponse response = generateProductResponse(path, hostHeader, xForwardedHost);

        // Store in cache
        responseCache.put(cacheKey, new CachedResponse(response, System.currentTimeMillis() + CACHE_TTL_MS));
        context.getLogger().log("Cache MISS, stored key: " + cacheKey);

        return response;
    }

    private String buildCacheKey(String path, String host) {
        // Normalize path but preserve host for tenant isolation
        String normalizedPath = path.replaceAll("/+", "/").toLowerCase();
        // Host included in key to prevent cross-tenant cache collision
        return (host != null ? host : "default") + "::" + normalizedPath;
    }

    private AwsProxyResponse generateProductResponse(String path, String host, String xForwardedHost) {
        AwsProxyResponse response = new AwsProxyResponse();
        response.setStatusCode(200);

        // Use X-Forwarded-Host to construct absolute URLs in response body
        String effectiveHost = xForwardedHost != null ? xForwardedHost : host;
        String baseUrl = "https://" + effectiveHost;

        String productId = extractProductId(path);
        String body = String.format(
            "{\"id\": \"%s\", \"name\": \"Product %s\", \"links\": {\"self\": \"%s/api/products/%s\", \"reviews\": \"%s/api/products/%s/reviews\"}}",
            productId, productId, baseUrl, productId, baseUrl, productId
        );

        response.setBody(body);
        Map<String, String> headers = new java.util.HashMap<>();
        headers.put("Content-Type", "application/json");
        headers.put("Cache-Control", "public, max-age=300");
        headers.put("X-Cache-Key", effectiveHost + "::" + path);
        response.setHeaders(headers);

        return response;
    }

    private String extractProductId(String path) {
        String[] parts = path.split("/");
        for (int i = 0; i < parts.length - 1; i++) {
            if ("products".equals(parts[i]) && i + 1 < parts.length) {
                return parts[i + 1].replaceAll("[^a-zA-Z0-9-]", "");
            }
        }
        return "unknown";
    }

    static class CachedResponse {
        private final AwsProxyResponse response;
        private final long expiresAt;

        CachedResponse(AwsProxyResponse response, long expiresAt) {
            this.response = response;
            this.expiresAt = expiresAt;
        }

        boolean isExpired() {
            return System.currentTimeMillis() > expiresAt;
        }

        AwsProxyResponse getResponse() {
            return response;
        }
    }
}
